const getJson = (name) => { try { return $(name).first().json; } catch (e) { return null; } };
const positions = getJson('T212 Get Positions') || [];
const summary = getJson('T212 Account Summary') || {};
const news = getJson('Yahoo Finance News') || {};
let positionsList = '';
if (Array.isArray(positions) && positions.length > 0) { positions.forEach(function(p) { const pplNum = parseFloat(p.ppl || 0); const cost = parseFloat(p.averagePrice || 0) * parseFloat(p.quantity || 0); const pnlPctNum = cost > 0 ? (pplNum / cost) * 100 : 0; const icon = pplNum >= 0 ? 'UP' : 'DN'; const isUS = (p.ticker || '').indexOf('_US_') !== -1; const ccy = isUS ? '$' : 'GBP'; positionsList += '[' + icon + '] ' + p.ticker + ': ' + ccy + parseFloat(p.currentPrice || 0).toFixed(2) + ' | P&L: GBP ' + pplNum.toFixed(2) + ' (' + pnlPctNum.toFixed(2) + '%)
'; }); } else { positionsList = 'Unable to fetch positions - check T212 API credentials'; }
let newsHeadlines = '';
try { const items = (news && news.news) || []; if (items.length === 0) { newsHeadlines = 'No overnight news available'; } else { items.slice(0, 5).forEach(function(n) { newsHeadlines += '- ' + n.title + '
'; }); } } catch (e) { newsHeadlines = 'Unable to fetch news'; }
const totalValue = parseFloat((summary && summary.totalValue) || 0).toFixed(2);
const cash = parseFloat((summary && summary.cash && summary.cash.availableToTrade) || 0).toFixed(2);
const totalPnl = parseFloat((summary && summary.investments && summary.investments.unrealizedProfitLoss) || 0).toFixed(2);
const today = new Date().toDateString();
const prompt = 'You are Del-Boy, a sharp and witty AI trading assistant analysing a UK ISA portfolio on Trading 212. Today is ' + today + '.

PORTFOLIO SUMMARY:
Total Value: GBP ' + totalValue + '
Cash Available: GBP ' + cash + '
Overall P&L: GBP ' + totalPnl + '

CURRENT POSITIONS:
' + positionsList + '
OVERNIGHT NEWS:
' + newsHeadlines + '
Provide a concise morning brief with:
1. TOP 3 positions to watch today and why
2. Any positions showing risk signals
3. One actionable trade idea
4. Overall market sentiment in one sentence

Keep it punchy - this is a pre-market brief. No disclaimers needed.';
return [{ json: { prompt: prompt, totalValue: totalValue, cash: cash, totalPnl: totalPnl, positionsList: positionsList } }];

// Extract Gemma response
const response = $input.first().json;
let analysis = '';

try {
  analysis = response?.choices?.[0]?.message?.content || 
             response?.response || 
             response?.message?.content || 
             'Gemma did not return a response - check model is loaded in Unsloth Studio';
} catch(e) {
  analysis = 'Error parsing Gemma response: ' + e.message;
}

// Get portfolio data
const portfolio = $('Build Gemma Prompt').first().json;

// Time
const now = new Date();
const timeStr = now.toLocaleTimeString('en-GB', { hour: '2-digit', minute: '2-digit' });
const dateStr = now.toDateString();

// Build Discord embed
const discordPayload = {
  embeds: [
    {
      title: "🚀 Del-Boy's Morning Trading Brief",
      description: `Lovely jubbly! Here's your brief for **${dateStr}**`,
      color: 3066993,
      fields: [
        {
          name: "💰 Portfolio Snapshot",
          value: `**Total Value:** £${portfolio.totalValue}\n**Cash:** £${portfolio.cash}\n**Overall P&L:** £${portfolio.totalPnl}`,
          inline: false
        },
        {
          name: "🤖 Gemma's Analysis",
          value: analysis.substring(0, 1024),
          inline: false
        },
        {
          name: "⏰ Key Times Today (BST)",
          value: "📈 Pre-market: 8:00am\n🇺🇸 US Opens: 2:30pm\n📞 Check for earnings calls",
          inline: false
        }
      ],
      footer: {
        text: `Generated ${timeStr} by Gemma on Unsloth Studio | Not financial advice`
      },
      timestamp: now.toISOString()
    }
  ]
};

return [{ json: discordPayload }];
